#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

int main(void) {
    long long n;
    if (scanf("%lld", &n) != 1) return 0;

    int fit_short = (n >= -32768LL && n <= 32767LL);
    int fit_long  = (n >= -2147483648LL && n <= 2147483647LL);
    int fit_ushort = (n >= 0 && n <= 65535LL);
    int fit_ulong  = (n >= 0 && n <= 18446744073709551615LL);

    if (fit_short) printf("Fits in short int\n");
    if (fit_long)  printf("Fits in long int\n");
    if (fit_ushort) printf("Fits in unsigned short int\n");
    if (fit_ulong) printf("Fits in unsigned long int\n");

    if (!fit_short && !fit_long && !fit_ushort && !fit_ulong) {
        printf("Does not fit in any type\n");
    }

    return 0;
}
